package com.ralysnd.ember

import android.content.Context
import android.util.Log
import java.io.File
import java.net.Authenticator
import java.net.HttpURLConnection
import java.net.InetSocketAddress
import java.net.PasswordAuthentication
import java.net.Proxy
import java.net.ServerSocket
import java.net.Socket
import java.net.URL

/**
 * One-shot tests for a V2Ray profile, run through a throwaway Xray
 * subprocess with a SOCKS-only config (generated by the Dart side): the
 * real delay is the time a request through that tunnel takes, and the
 * speed test downloads through it — the same idea as v2rayNG's
 * measureOutboundDelay, adapted to the subprocess core.
 */
object XrayTester {
    private const val TAG = "XrayTester"

    // Build 2125 (audit A25-06 / P-10): the last CUMULATIVE
    // counter values this process has reported, per
    // "<apiPort>|<counter>". The stats queries no longer
    // drain the core's counters with -reset: the reset used
    // to execute server-side when the query ran, BEFORE the
    // client read or parsed the reply — a parse miss or a
    // destroyed process after the answer had already reset
    // the counters, and that traffic vanished from the
    // accounting permanently. Now the queries read the
    // cumulative counters and the caller-facing value is
    // the delta against the remembered reading, so a
    // failed poll loses nothing: the next successful one
    // reports everything since the last success.
    private val cumulativeSeen =
        java.util.concurrent.ConcurrentHashMap<String, Long>()

    /** The caller-facing delta for one counter: the growth
     *  since the last reported reading. A cumulative BELOW
     *  the remembered one means the core restarted (its
     *  counters zeroed) — the whole current value is then
     *  this interval's traffic. Only called for values that
     *  are actually being returned, so a failed poll never
     *  advances the baseline. */
    private fun deltaSinceLast(key: String, cumulative: Long): Long {
        val prev = cumulativeSeen.put(key, cumulative) ?: 0L
        return if (cumulative >= prev) cumulative - prev else cumulative
    }

    /** A port base for test instances; rotated per call to avoid clashes. */
    @Volatile
    private var nextPort = 11080

    /**
     * LAN sharing (build 2062, feature queue #2): the SOCKS
     * username/password auth for the live tunnel's
     * password-protected inbound. `java.net` asks the default
     * [Authenticator] when a SOCKS5 proxy demands auth, so one
     * installed authenticator serves every probe — but it
     * answers ONLY for the exact loopback host + the stored
     * port, and only while credentials are set, so it can
     * never leak the password to another host or a test core.
     * Installed once; empty credentials clear the fields.
     */
    private object SocksAuth : Authenticator() {
        @Volatile var user = ""
        @Volatile var pass = ""
        @Volatile var port = 0

        override fun getPasswordAuthentication(): PasswordAuthentication? {
            if (requestingHost != "127.0.0.1" || requestingPort != port) {
                return null
            }
            if (user.isEmpty() || pass.isEmpty()) return null
            return PasswordAuthentication(user, pass.toCharArray())
        }
    }

    @Volatile
    private var socksAuthInstalled = false

    /** Sets (or clears, when empty) the SOCKS credentials for [port]. */
    private fun setSocksAuth(user: String, pass: String, port: Int) {
        if (!socksAuthInstalled) {
            Authenticator.setDefault(SocksAuth)
            socksAuthInstalled = true
        }
        SocksAuth.user = user
        SocksAuth.pass = pass
        SocksAuth.port = port
    }

    /**
     * Build 2057 (audit F-M7): the test log's 1 MB rotation — the
     * same rule as XrayVpnService.rotateLogIfLarge, kept local
     * because the tester is a standalone object, not a service.
     */
    private fun rotateLogIfLarge(file: File) {
        try {
            if (file.exists() && file.length() > 1024 * 1024) {
                file.renameTo(File(file.parentFile, "${file.name}.old"))
            }
        } catch (e: Exception) {
            // Logging must never break the test.
        }
    }

    @Synchronized
    private fun takePort(): Int {
        val p = nextPort
        nextPort += 2
        if (nextPort > 11260) nextPort = 11080
        return p
    }

    /**
     * A port from the test range that nothing holds right now
     * (build 2061, feature queue #1): the rotation is only a
     * candidate list — a stale test core that outlived its kill
     * would otherwise hand the next test a port whose SOCKS
     * answers for the WRONG config. The bind probe closes that
     * hole: a held candidate is skipped, never used. -1 when
     * the whole range is busy.
     */
    @Synchronized
    private fun takeFreePort(): Int {
        repeat(91) {
            val p = takePort()
            try {
                ServerSocket(p).use { return p }
            } catch (e: Exception) {
                // Held — try the next candidate.
            }
        }
        return -1
    }

    
    /**
     * [measureDelay] plus the exit identity through the SAME
     * throwaway instance (build 2032, the v2go fold-in): a delay
     * test that also learns where the profile exits, so the list
     * can show the exit IP/country without a full connect. The
     * exit lookup is best-effort and never fails the delay.
     * [timeoutMs] (build 2109): the per-request timeout the
     * `delayTestTimeoutSec` setting carries — 8000 when the
     * caller does not pass it (the fixed value of every build
     * ≤2108). Under a [budgetMs] the request timeout is the
     * smaller of the two, so a longer setting is honored only
     * up to the caller's overall budget.
     */
    fun measureDelayEx(
        context: Context,
        configJson: String,
        rounds: Int = 2,
        budgetMs: Long = 0,
        timeoutMs: Int = 8000,
    ): Map<String, Any> {
        val port = takeFreePort()
        if (port < 0) {
            return mapOf("ms" to -1L, "ip" to "", "countryCode" to "")
        }
        val config = configJson.replace("\"port\": 0", "\"port\": $port")
            .replace("\"port\":0", "\"port\":$port")
        // Build 2101 (settings-dns-2099-diagnosis.md, S5): the
        // bulk Test-All pass passes rounds = 1 and a ~10 s
        // overall budget — one request round instead of two,
        // and a dead config burns the budget, not the old
        // ~76 s worst case (12 s port wait + 2 rounds × 2
        // targets × 8 s timeouts + the exit lookup). The
        // defaults (2 rounds, no budget) keep the single-profile
        // test exactly as before.
        val deadline = if (budgetMs > 0) {
            System.currentTimeMillis() + budgetMs
        } else {
            0L
        }
        val proc = startInstance(context, config, port, budgetMs)
            ?: return mapOf("ms" to -1L, "ip" to "", "countryCode" to "")
        try {
            var best = Long.MAX_VALUE
            repeat(rounds.coerceIn(1, 2)) {
                var requestTimeoutMs = timeoutMs
                if (deadline > 0) {
                    val left = deadline - System.currentTimeMillis()
                    if (left <= 0) return@repeat
                    requestTimeoutMs = minOf(timeoutMs.toLong(), left).toInt()
                }
                val ms = timeRequest(port, timeoutMs = requestTimeoutMs)
                if (ms >= 0 && ms < best) best = ms
            }
            if (best == Long.MAX_VALUE) {
                return mapOf("ms" to -1L, "ip" to "", "countryCode" to "")
            }
            // The exit lookup is best-effort; under a budget it
            // runs only when time clearly remains for it.
            val exit = if (deadline > 0 &&
                deadline - System.currentTimeMillis() < 2000
            ) {
                null
            } else {
                exitInfo(port)
            }
            return mapOf(
                "ms" to best,
                "ip" to (exit?.get("ip") ?: ""),
                "countryCode" to (exit?.get("countryCode") ?: ""),
            )
        } finally {
            kill(proc)
        }
    }

    /**
     * The endurance qualification of [configJson] (build 2029A):
     * three real requests at t=0, +2.5 s and +5.4 s over ONE
     * keep-alive connection through a throwaway instance. The
     * same socket is reused on purpose: filtered networks in
     * the target region let a handshake through and then freeze
     * the session seconds later, and a fresh socket per probe
     * would grade that a pass. Returns per-probe ms (-1 on
     * failure) and "held" = 1 when all three answered.
     */
    fun endurance(context: Context, configJson: String): Map<String, Long> {
        val failed = mapOf("p0" to -1L, "p1" to -1L, "p2" to -1L, "held" to 0L)
        val port = takeFreePort()
        if (port < 0) return failed
        val config = configJson.replace("\"port\": 0", "\"port\": $port")
            .replace("\"port\":0", "\"port\":$port")
        val proc = startInstance(context, config, port) ?: return failed
        try {
            return enduranceOnPort(port)
        } finally {
            kill(proc)
        }
    }

    /**
     * The endurance probes against a core ALREADY listening on
     * [port] (build 2061): the socket work of [endurance],
     * factored out so the sandbox test can run the same hold
     * check on its own instance instead of starting a second
     * core for it.
     */
    private fun enduranceOnPort(port: Int): Map<String, Long> {
        val failed = mapOf("p0" to -1L, "p1" to -1L, "p2" to -1L, "held" to 0L)
        var socket: Socket? = null
        try {
            val host = "connectivitycheck.gstatic.com"
            val s = Socket()
            socket = s
            s.connect(InetSocketAddress("127.0.0.1", port), 5000)
            s.soTimeout = 7000
            val out = s.getOutputStream()
            val input = s.getInputStream()
            // SOCKS5 greeting + CONNECT by domain (the core
            // resolves it), once for the whole run.
            out.write(byteArrayOf(5, 1, 0))
            out.flush()
            val greeting = readExactly(input, 2) ?: return failed
            if (greeting[0].toInt() != 5) return failed
            val hostBytes = host.toByteArray(Charsets.US_ASCII)
            out.write(
                byteArrayOf(5, 1, 0, 3, hostBytes.size.toByte()) +
                    hostBytes + byteArrayOf(0, 80),
            )
            out.flush()
            val head = readExactly(input, 4) ?: return failed
            if (head[0].toInt() != 5 || head[1].toInt() != 0) return failed
            when (head[3].toInt()) {
                1 -> readExactly(input, 6)
                3 -> {
                    val len = readExactly(input, 1) ?: return failed
                    readExactly(input, (len[0].toInt() and 0xff) + 2)
                }
                4 -> readExactly(input, 18)
                else -> return failed
            } ?: return failed

            fun probe(): Long {
                val started = System.nanoTime()
                return try {
                    out.write(
                        ("HEAD /generate_204 HTTP/1.1\r\nHost: $host\r\n" +
                            "Connection: keep-alive\r\n\r\n")
                            .toByteArray(Charsets.US_ASCII),
                    )
                    out.flush()
                    val status = readHttpStatus(input) ?: return -1
                    if (status == 204 || status == 200) {
                        (System.nanoTime() - started) / 1_000_000
                    } else {
                        -1
                    }
                } catch (e: Exception) {
                    -1
                }
            }

            val t0 = System.nanoTime()
            val p0 = probe()
            sleepUntil(t0 + 2_500_000_000L)
            val p1 = probe()
            sleepUntil(t0 + 5_400_000_000L)
            val p2 = probe()
            val held = if (p0 >= 0 && p1 >= 0 && p2 >= 0) 1L else 0L
            return mapOf("p0" to p0, "p1" to p1, "p2" to p2, "held" to held)
        } catch (e: Exception) {
            Log.w(TAG, "endurance test failed", e)
            return failed
        } finally {
            try {
                socket?.close()
            } catch (e: Exception) {
                // Already gone.
            }
        }
    }

    /**
     * The sandbox config test (build 2061, feature queue #1):
     * ONE throwaway instance proves a config end to end —
     * delay, endurance hold, exit identity — without touching
     * the live tunnel. The instance listens on a genuinely
     * free port ([takeFreePort]), and its temp config is
     * deleted when the test ends. Returns the verdict map:
     * ok 1/0, ms, p0/p1/p2, held 1/0, ip, countryCode,
     * country, error '' when ok. `error` names the failing
     * stage in plain words; a config that answers but does
     * not hold is ok=1 with held=0 — the caller grades it
     * "unstable", not "failed".
     * [timeoutMs] (build 2109): the per-request timeout of the
     * delay rounds — the `delayTestTimeoutSec` setting, 8000
     * when the caller does not pass it (the fixed value of
     * every build ≤2108). The endurance hold keeps its own
     * fixed schedule.
     */
    fun sandboxTest(
        context: Context,
        configJson: String,
        timeoutMs: Int = 8000,
    ): Map<String, Any> {
        fun failed(error: String): Map<String, Any> = mapOf(
            "ok" to 0,
            "ms" to -1L,
            "p0" to -1L,
            "p1" to -1L,
            "p2" to -1L,
            "held" to 0L,
            "ip" to "",
            "countryCode" to "",
            "country" to "",
            "error" to error,
        )
        val port = takeFreePort()
        if (port < 0) return failed("no free port for the sandbox test")
        val config = configJson.replace("\"port\": 0", "\"port\": $port")
            .replace("\"port\":0", "\"port\":$port")
        val configFile = File(
            File(XrayVpnService.workDir(context), "test"),
            "config-$port.json",
        )
        val proc = startInstance(context, config, port)
            ?: run {
                try {
                    configFile.delete()
                } catch (e: Exception) {
                    // A leftover temp config is overwritten by
                    // the next test on this port.
                }
                return failed(
                    "the sandbox core did not start — the config may be rejected",
                )
            }
        try {
            var best = Long.MAX_VALUE
            repeat(2) {
                val ms = timeRequest(port, timeoutMs = timeoutMs)
                if (ms >= 0 && ms < best) best = ms
            }
            if (best == Long.MAX_VALUE) {
                return failed("the config did not answer through the tunnel")
            }
            val held = enduranceOnPort(port)
            val exit = exitInfo(port)
            return mapOf(
                "ok" to 1,
                "ms" to best,
                "p0" to (held["p0"] ?: -1L),
                "p1" to (held["p1"] ?: -1L),
                "p2" to (held["p2"] ?: -1L),
                "held" to (held["held"] ?: 0L),
                "ip" to (exit?.get("ip") ?: ""),
                "countryCode" to (exit?.get("countryCode") ?: ""),
                "country" to (exit?.get("country") ?: ""),
                "error" to "",
            )
        } finally {
            kill(proc)
            try {
                configFile.delete()
            } catch (e: Exception) {
                // A leftover temp config is overwritten by the
                // next test on this port.
            }
        }
    }

    /**
     * The proxied service reachability check (build 2091,
     * feature-watch 2026-11-16, FlClash 0.9.x): ONE throwaway
     * instance asks each host in [hosts] for a real HTTPS HEAD
     * through the config, on a free port, without touching the
     * live tunnel — the same discipline as [sandboxTest] (free
     * port, temp config deleted, instance killed on every path).
     * Any HTTP status line proves the service answered through
     * the node; only "no answer" counts as unreachable, so the
     * per-host result is `{"ms": n|-1, "status": code|0}` and
     * the map is `{"ok": 1/0, "error": "", "results":
     * {host: {...}}}`. The probes run four at a time so a dead
     * node costs ~12 s, not six timeouts in a row; each probe
     * is a plain HEAD on `/` with redirects off — the status
     * recorded is the service's own first answer.
     */
    fun serviceCheck(
        context: Context,
        configJson: String,
        hosts: List<String>,
    ): Map<String, Any> {
        fun failed(error: String): Map<String, Any> = mapOf(
            "ok" to 0,
            "error" to error,
            "results" to emptyMap<String, Any>(),
        )
        val cleanHosts = hosts.map { it.trim() }
            .filter { it.isNotEmpty() }.distinct().take(8)
        if (cleanHosts.isEmpty()) return failed("no service to check")
        val port = takeFreePort()
        if (port < 0) return failed("no free port for the service check")
        val config = configJson.replace("\"port\": 0", "\"port\": $port")
            .replace("\"port\":0", "\"port\":$port")
        val configFile = File(
            File(XrayVpnService.workDir(context), "test"),
            "config-$port.json",
        )
        val proc = startInstance(context, config, port)
            ?: run {
                try {
                    configFile.delete()
                } catch (e: Exception) {
                    // A leftover temp config is overwritten by
                    // the next test on this port.
                }
                return failed(
                    "the service-check core did not start — the config may be rejected",
                )
            }
        try {
            // Test cores are noauth: clear any LAN-sharing
            // credentials left by a live-tunnel probe, the
            // same way timeRequest does for its callers.
            setSocksAuth("", "", port)
            val pool = java.util.concurrent.Executors.newFixedThreadPool(4)
            try {
                val futures = cleanHosts.associateWith { host ->
                    pool.submit<Map<String, Any>> { probeService(port, host) }
                }
                val results = mutableMapOf<String, Any>()
                for ((host, future) in futures) {
                    results[host] = try {
                        future.get(20, java.util.concurrent.TimeUnit.SECONDS)
                    } catch (e: Exception) {
                        mapOf("ms" to -1L, "status" to 0)
                    }
                }
                return mapOf("ok" to 1, "error" to "", "results" to results)
            } finally {
                pool.shutdownNow()
            }
        } finally {
            kill(proc)
            try {
                configFile.delete()
            } catch (e: Exception) {
                // A leftover temp config is overwritten by the
                // next test on this port.
            }
        }
    }

    /** One HTTPS HEAD through the throwaway core on [port]: the
     * status the service answered with, or -1/0 on no answer.
     * Redirects are off — the status recorded is the service's
     * own first answer, and a 301 is as much an answer as a 200.
     */
    private fun probeService(port: Int, host: String): Map<String, Any> {
        var conn: HttpURLConnection? = null
        return try {
            val started = System.nanoTime()
            conn = openViaSocks(URL("https://$host/"), port)
            conn.connectTimeout = 6000
            conn.readTimeout = 6000
            conn.instanceFollowRedirects = false
            conn.requestMethod = "HEAD"
            val code = conn.responseCode
            mapOf(
                "ms" to (System.nanoTime() - started) / 1_000_000,
                "status" to code,
            )
        } catch (e: Exception) {
            mapOf("ms" to -1L, "status" to 0)
        } finally {
            try {
                conn?.disconnect()
            } catch (e: Exception) {
                // Already gone.
            }
        }
    }

    /** Reads exactly [n] bytes or returns null at EOF/timeout. */
    private fun readExactly(input: java.io.InputStream, n: Int): ByteArray? {
        val buffer = ByteArray(n)
        var read = 0
        while (read < n) {
            val count = try {
                input.read(buffer, read, n - read)
            } catch (e: Exception) {
                return null
            }
            if (count < 0) return null
            read += count
        }
        return buffer
    }

    /**
     * Reads one HTTP response head (through the blank line) on
     * a keep-alive connection and returns its status code. A
     * 204 has no body, so the head is the whole response and
     * the connection stays usable for the next probe.
     */
    private fun readHttpStatus(input: java.io.InputStream): Int? {
        val buffer = StringBuilder()
        var matched = 0 // bytes of the "\r\n\r\n" terminator seen
        while (buffer.length < 8192) {
            val b = try {
                input.read()
            } catch (e: Exception) {
                return null
            }
            if (b < 0) return null
            buffer.append(b.toChar())
            matched = when {
                b == '\r'.code && (matched == 0 || matched == 2) -> matched + 1
                b == '\n'.code && (matched == 1 || matched == 3) -> matched + 1
                else -> 0
            }
            if (matched == 4) break
        }
        val firstLine = buffer.lineSequence().firstOrNull() ?: return null
        return firstLine.split(' ').getOrNull(1)?.toIntOrNull()
    }

    private fun sleepUntil(deadlineNanos: Long) {
        var remaining = deadlineNanos - System.nanoTime()
        while (remaining > 0) {
            try {
                Thread.sleep(remaining / 1_000_000, (remaining % 1_000_000).toInt())
            } catch (e: InterruptedException) {
                return
            }
            remaining = deadlineNanos - System.nanoTime()
        }
    }

    /**
     * Downloads through a throwaway instance of [configJson] for up to
     * [seconds] and returns the average downlink in bytes per second,
     * or -1 on failure.
     */
    fun speedTest(context: Context, configJson: String, seconds: Int = 8): Long {
        val port = takeFreePort()
        if (port < 0) return -1
        val config = configJson.replace("\"port\": 0", "\"port\": $port")
            .replace("\"port\":0", "\"port\":$port")
        val proc = startInstance(context, config, port) ?: return -1
        try {
            val url = URL("https://speed.cloudflare.com/__down?bytes=50000000")
            val conn = openViaSocks(url, port)
            conn.connectTimeout = 8000
            conn.readTimeout = 15000
            val started = System.nanoTime()
            var total = 0L
            val deadline = started + seconds * 1_000_000_000L
            conn.inputStream.use { input ->
                val buffer = ByteArray(64 * 1024)
                while (System.nanoTime() < deadline) {
                    val n = input.read(buffer)
                    if (n < 0) break
                    total += n
                }
            }
            val elapsed = (System.nanoTime() - started) / 1_000_000_000.0
            if (elapsed <= 0 || total == 0L) return -1
            return (total / elapsed).toLong()
        } catch (e: Exception) {
            Log.w(TAG, "speed test failed", e)
            return -1
        } finally {
            kill(proc)
        }
    }

    /**
     * Validates [configJson] with the bundled core binary itself
     * (`run -test`): null when the core accepts the config, the
     * core's own output (trimmed) when it rejects it. Backs the
     * profile editor's save gate for anti-filter-shaped configs
     * (build 2026, Stage A): a shape the core refuses is never
     * saved silently.
     */
    fun validateConfig(context: Context, configJson: String): String? {
        val dir = XrayVpnService.workDir(context).apply { mkdirs() }
        val testDir = File(dir, "test").apply { mkdirs() }
        val configFile = File(testDir, "validate.json")
        // Build 2060 (grouped sweep): the -test process was never
        // reaped on the exception path — a readText() throw left a
        // libxray process running with no owner. The process is now
        // hoisted out of the try and destroyed in a finally on
        // every path; the wait comes before the read, so a hung
        // core cannot wedge the read either.
        var proc: Process? = null
        return try {
            // Build 2071 (review §9 item 8): atomic write
            // (tmp + sync + rename) like every other store —
            // a kill mid-write used to be able to leave the
            // test config torn for the next run to read.
            AtomicFile.writeText(configFile, configJson)
            proc = ProcessBuilder(
                File(context.applicationInfo.nativeLibraryDir, "libxray.so").absolutePath,
                "run", "-test", "-c", configFile.absolutePath,
            )
                .directory(dir)
                .redirectErrorStream(true)
                .start()
            if (!proc.waitFor(15, java.util.concurrent.TimeUnit.SECONDS)) {
                proc.destroyForcibly()
                return "the core did not answer the validation in time"
            }
            val out = proc.inputStream.bufferedReader().readText()
            if (proc.exitValue() == 0) {
                null
            } else {
                out.trim().ifEmpty { "the core rejected the config" }
            }
        } catch (e: Exception) {
            Log.w(TAG, "config validation failed to run", e)
            "config validation failed: ${e.message}"
        } finally {
            proc?.destroyForcibly()
        }
    }

    /**
     * One real proxied request through the tunnel ALREADY running
     * on [port] (the live service's SOCKS inbound, not a test
     * instance): its delay in ms, or -1 when the tunnel does not
     * answer. The adaptive failover's health probe (build 2026).
     * LAN sharing (build 2062): [user]/[pass] authenticate to a
     * password-protected inbound; ''/'' is the noauth behaviour
     * of every earlier build.
     */
    fun tunnelCheck(port: Int, user: String = "", pass: String = ""): Long =
        timeRequest(port, user, pass)

    /**
     * The exit identity of the tunnel ALREADY running on [port] (the
     * live service's SOCKS inbound, not a test instance): asks
     * Cloudflare's trace endpoint through the tunnel for the exit IP
     * and country code. Best-effort only — returns null on any
     * failure and never affects the connection.
     * LAN sharing (build 2062): [user]/[pass] authenticate to a
     * password-protected inbound; ''/'' is noauth.
     *
     * Build 2087 (analysis A5) — REMOVED, named per the
     * no-silent-removal rule: the old second attempt fetched
     * http://ip-api.com/... as a fallback. It could never succeed:
     * since build 2084 the app's network security config permits
     * cleartext only for the two gstatic probe hosts, so the
     * platform refused the request in-process every time (silently
     * masked by this primary), and ip-api.com offers no free HTTPS
     * endpoint to switch it to. The trace primary above returns the
     * same ip + country code the fallback existed for.
     */
    fun exitInfo(port: Int, user: String = "", pass: String = ""): Map<String, String>? {
        setSocksAuth(user, pass, port)
        try {
            val conn = openViaSocks(URL("https://www.cloudflare.com/cdn-cgi/trace"), port)
            conn.connectTimeout = 6000
            conn.readTimeout = 6000
            val text = conn.inputStream.bufferedReader().readText()
            var ip = ""
            var loc = ""
            for (line in text.lineSequence()) {
                when {
                    line.startsWith("ip=") -> ip = line.substring(3).trim()
                    line.startsWith("loc=") -> loc = line.substring(4).trim()
                }
            }
            if (ip.isNotEmpty()) return mapOf("ip" to ip, "countryCode" to loc)
        } catch (e: Exception) {
            Log.w(TAG, "exit info (trace) failed", e)
        }
        return null
    }

    /**
     * The running tunnel core's "proxy" outbound traffic since the
     * previous call, from the core's own statistics API: the query
     * resets the counters, so each returned value is a delta.
     * Keys "up"/"down" in bytes; null when the query fails.
     *
     * Build 2050 (audit B-H1): ONE `statsquery` process returns
     * both counters. This used to spawn the multi-MB core binary
     * TWICE per call — two full Go runtime starts every 2 s poll,
     * ≈3,600 process creations an hour, on idle tunnels too. The
     * legacy two-call path stays as the fallback for a core whose
     * statsquery fails, so nothing is lost if it ever does.
     */
    fun trafficStats(context: Context, apiPort: Int): Map<String, Long>? {
        // Build 2095 (third-pass audit 6-1): the legacy
        // two-process fallback runs only when the combined
        // call itself failed to RUN — it used to run on
        // every 2 s poll whenever the counters were absent,
        // doubling the process spawns for the whole session.
        val (both, ranOk) = statsQueryBoth(context, apiPort)
        if (both != null) return both
        if (ranOk) return null
        // Build 2126 (audit A26-11): both RAW readings
        // first, both deltas after — up to 2125 counter()
        // converted to a delta as it read, so when the up
        // query succeeded and the down query failed, the
        // up baseline had already advanced and that
        // traffic was discarded unreported. The combined
        // path above has always converted only after both
        // parse; the legacy path now matches it.
        val upName = "outbound>>>proxy>>>traffic>>>uplink"
        val downName = "outbound>>>proxy>>>traffic>>>downlink"
        val upRaw = counter(context, apiPort, upName) ?: return null
        val downRaw = counter(context, apiPort, downName) ?: return null
        return mapOf(
            "up" to deltaSinceLast("$apiPort|$upName", upRaw),
            "down" to deltaSinceLast("$apiPort|$downName", downRaw),
        )
    }

    /**
     * One process, both counters, via `api statsquery`.
     * Returns the DELTAS since the last reported reading
     * (or null) plus whether the call itself ran — a parse
     * miss is a ran call with no data, not a failure worth
     * the legacy fallback. Build 2125 (audit A25-06): no
     * -reset — see [cumulativeSeen]; the values parsed here
     * are the core's cumulative counters, converted to
     * deltas only after BOTH parse, so a miss consumes
     * nothing.
     */
    private fun statsQueryBoth(
        context: Context,
        apiPort: Int,
    ): Pair<Map<String, Long>?, Boolean> {
        val proc = try {
            ProcessBuilder(
                File(context.applicationInfo.nativeLibraryDir, "libxray.so").absolutePath,
                "api", "statsquery",
                "--server=127.0.0.1:$apiPort",
                "-pattern", "outbound>>>proxy>>>traffic>>>",
            ).redirectErrorStream(true).start()
        } catch (e: Exception) {
            Log.w(TAG, "statsquery did not start", e)
            return null to false
        }
        return try {
            // Build 2095 (audit 6-1): wait BEFORE reading —
            // readText() blocks until the process exits, so
            // the old order made the 5 s timeout unenforceable
            // and a wedged query hung the caller forever. The
            // output is a few hundred bytes; wait-then-read
            // cannot fill the pipe.
            if (!proc.waitFor(5, java.util.concurrent.TimeUnit.SECONDS)) {
                proc.destroyForcibly()
                return null to false
            }
            if (proc.exitValue() != 0) return null to false
            val out = proc.inputStream.bufferedReader().readText()
            // Entries look like {"name": "...", "value": 123}; a
            // zero counter is printed WITHOUT a "value" field.
            // Parse per entry block so a missing value can never
            // borrow the next counter's number.
            fun entryValue(name: String): Long? {
                for (block in Regex("\\{[^{}]*\\}").findAll(out)) {
                    val text = block.value
                    if (!text.contains("\"$name\"")) continue
                    return Regex("\"value\"\\s*:\\s*(\\d+)").find(text)
                        ?.groupValues?.get(1)?.toLong() ?: 0L
                }
                return null
            }
            val up = entryValue("outbound>>>proxy>>>traffic>>>uplink")
                ?: return null to true
            val down = entryValue("outbound>>>proxy>>>traffic>>>downlink")
                ?: return null to true
            // The baseline keys are the full counter names —
            // the SAME keys the legacy counter() path uses,
            // so a poll that falls back mid-session continues
            // from the combined path's baseline instead of
            // re-reporting the whole cumulative.
            mapOf(
                "up" to deltaSinceLast(
                    "$apiPort|outbound>>>proxy>>>traffic>>>uplink", up,
                ),
                "down" to deltaSinceLast(
                    "$apiPort|outbound>>>proxy>>>traffic>>>downlink", down,
                ),
            ) to true
        } catch (e: Exception) {
            Log.w(TAG, "statsquery failed", e)
            null to false
        }
    }

    /** The legacy single-counter query (`api stats`).
     *  Build 2125 (audit A25-06): no -reset — the reply is
     *  the cumulative counter, converted to a delta against
     *  the remembered reading (see [cumulativeSeen]). */
    private fun counter(context: Context, apiPort: Int, name: String): Long? {
        val proc = try {
            ProcessBuilder(
                File(context.applicationInfo.nativeLibraryDir, "libxray.so").absolutePath,
                "api", "stats",
                "--server=127.0.0.1:$apiPort",
                "-name", name,
            ).redirectErrorStream(true).start()
        } catch (e: Exception) {
            Log.w(TAG, "stats query did not start", e)
            return null
        }
        return try {
            // Build 2095 (audit 6-1): wait-then-read, as in
            // statsQueryBoth — the timeout is real now.
            if (!proc.waitFor(5, java.util.concurrent.TimeUnit.SECONDS)) {
                proc.destroyForcibly()
                return null
            }
            if (proc.exitValue() != 0) return null
            val out = proc.inputStream.bufferedReader().readText()
            // The reply is the counter as JSON; a zero counter is
            // printed without a "value" field at all.
            val cumulative = Regex("\"value\"\\s*:\\s*(\\d+)").find(out)
                ?.groupValues?.get(1)?.toLong() ?: 0L
            // Build 2126 (A26-11): the RAW cumulative —
            // the caller converts to deltas only once
            // BOTH counters are in (see trafficStats).
            cumulative
        } catch (e: Exception) {
            Log.w(TAG, "stats query failed", e)
            null
        }
    }

    /** Starts a test instance and waits for its SOCKS port.
     * [budgetMs] (build 2101) caps the port wait when the
     * caller runs under an overall deadline; 0 = the full
     * 12 s wait, as before. */
    private fun startInstance(
        context: Context,
        configJson: String,
        port: Int,
        budgetMs: Long = 0,
    ): Process? {
        val dir = File(XrayVpnService.workDir(context), "test").apply { mkdirs() }
        val configFile = File(dir, "config-$port.json")
        return try {
            // Build 2071: atomic write, as in validateConfig.
            AtomicFile.writeText(configFile, configJson)
            val log = File(dir, "test-$port.log")
            // Build 2057 (audit F-M7): the same 1 MB rotation as
            // the service — a test instance appends on every run,
            // and a failing profile's test log would otherwise grow
            // without bound next to the service logs.
            rotateLogIfLarge(log)
            val proc = ProcessBuilder(
                File(context.applicationInfo.nativeLibraryDir, "libxray.so").absolutePath,
                "run", "-c", configFile.absolutePath,
            )
                .directory(dir)
                .redirectErrorStream(true)
                .redirectOutput(ProcessBuilder.Redirect.appendTo(log))
                .start()
            val waitMs = if (budgetMs > 0) minOf(12000L, budgetMs) else 12000L
            if (waitForPort(proc, port, waitMs)) proc else {
                kill(proc)
                null
            }
        } catch (e: Exception) {
            Log.e(TAG, "the test instance did not start", e)
            null
        }
    }

    private fun waitForPort(proc: Process, port: Int, timeoutMs: Long): Boolean {
        val deadline = System.currentTimeMillis() + timeoutMs
        while (System.currentTimeMillis() < deadline) {
            if (!proc.isAlive) return false
            try {
                Socket().use { s ->
                    s.connect(InetSocketAddress("127.0.0.1", port), 300)
                    return true
                }
            } catch (e: Exception) {
                try {
                    Thread.sleep(120)
                } catch (ie: InterruptedException) {
                    return false
                }
            }
        }
        return false
    }

    private fun openViaSocks(url: URL, port: Int): HttpURLConnection {
        val proxy = Proxy(Proxy.Type.SOCKS, InetSocketAddress("127.0.0.1", port))
        return url.openConnection(proxy) as HttpURLConnection
    }

    /**
     * Times a full request through the tunnel on [port]: a 204 from a
     * generate_204 endpoint, first byte counted at the status line.
     * LAN sharing (build 2062): [user]/[pass] authenticate to a
     * password-protected inbound (set — or cleared when empty —
     * before the request); test cores are noauth, so their callers
     * pass the defaults and the fields are cleared for them.
     */
    private fun timeRequest(
        port: Int,
        user: String = "",
        pass: String = "",
        timeoutMs: Int = 8000,
    ): Long {
        setSocksAuth(user, pass, port)
        for (target in listOf(
            "http://www.gstatic.com/generate_204",
            "https://www.google.com/generate_204",
        )) {
            try {
                val started = System.nanoTime()
                val conn = openViaSocks(URL(target), port)
                conn.connectTimeout = timeoutMs
                conn.readTimeout = timeoutMs
                conn.instanceFollowRedirects = false
                val code = conn.responseCode
                conn.disconnect()
                if (code == 204 || code == 200) {
                    return (System.nanoTime() - started) / 1_000_000
                }
            } catch (e: Exception) {
                // Try the next target.
            }
        }
        return -1
    }

    private fun kill(p: Process) {
        // Build 2054 (audit F-M1): the shared kill — the old
        // destroy + 500 ms + forcibly with NO post-forcible wait
        // could return while a test core still held its port.
        ProcessKill.kill(p, destroyGraceMs = 500, forcibleWaitMs = 2500)
    }
}
